  const cards = "<article id=\"entry-dgp-886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγίοχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 886 na letra α · nº geral 886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">portador da égide. 〈αἰγίς, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγίπαν, ᾶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 887 na letra α · nº geral 887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Egipã; Pã de pés de bode. 〈αἴξ, Πάν〉</p></section></article>\n<article id=\"entry-dgp-888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγίπλαγκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 888 na letra α · nº geral 888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onde vagueiam cabras. 〈αἴξ, πλάζω〉</p></section></article>\n<article id=\"entry-dgp-889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγίπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 889 na letra α · nº geral 889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ποδος que tem pés de cabra. 〈αἴξ, πούς〉</p></section></article>\n<article id=\"entry-dgp-890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγίπυρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 890 na letra α · nº geral 890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trigo de cabras. 〈αἴξ, πυρός〉</p></section></article>\n<article id=\"entry-dgp-891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 891 na letra α · nº geral 891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele de cabra; capa de pele de cabra 2 égi- de, escudo feito com pele de cabra 3 nó de pinho 4 tem­pestade; furacão. 〈αἴξ〉</p></section></article>\n<article id=\"entry-dgp-892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴγισθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 892 na letra α · nº geral 892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Egisto, filho de Tieste e assassino de Agamenão.</p></section></article>\n<article id=\"entry-dgp-893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγλᾶς</h1><div class=\"entry-meta\"><span>DGP · ordem 893 na letra α · nº geral 893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = αἰγλήεις.</p></section></article>\n<article id=\"entry-dgp-894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴγλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 894 na letra α · nº geral 894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 brilho; claridade 2 esplendor 3 glória 4 pl. tochas acesas.</p></section></article>\n<article id=\"entry-dgp-895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγλήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 895 na letra α · nº geral 895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">brilhante; refulgente. 〈αἴγλη〉</p></section></article>\n<article id=\"entry-dgp-896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγοθηρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 896 na letra α · nº geral 896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo à caça de cabritos monteses. 〈αἴξ, θηράω〉</p></section></article>\n<article id=\"entry-dgp-897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγόκερως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 897 na letra α · nº geral 897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ω, dat. ῳ, ac. ων, tard. 1 que tem chifres de cabra ♦ ὁ αἰγόκερως 2 Capricórnio, signo do zodíaco. 〈αἴξ, κέρας〉</p></section></article>\n<article id=\"entry-dgp-898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγοπρόσωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 898 na letra α · nº geral 898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem cara de bode ou de cabra. 〈αἴξ, πρόσωπον〉</p></section></article>\n<article id=\"entry-dgp-899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγὸς ποταμοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 899 na letra α · nº geral 899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Egos Pótamos, “Rio da cabra”, rio e cidade do Quersoneso, na Trácia.</p></section></article>\n<article id=\"entry-dgp-900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγυπιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 900 na letra α · nº geral 900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abutre.</p></section></article>\n<article id=\"entry-dgp-901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰγυπτιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 901 na letra α · nº geral 901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falar a língua egípcia 2 falar como um egípcio; ser astuto como um egípcio 3 estar como o Egito, i.e., debaixo d’água, inundado. 〈Αἰγύπτιος〉</p></section></article>\n<article id=\"entry-dgp-902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγυπτιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 902 na letra α · nº geral 902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Αἰγύπτιος. 〈Αἴγυπτος〉</p></section></article>\n<article id=\"entry-dgp-903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγύπτιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 903 na letra α · nº geral 903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 egípcio ♦ ὁ Αἰγύπτιος 2 Egípcio, n. de homem. 〈Αἴγυπτος〉</p></section></article>\n<article id=\"entry-dgp-904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγυπτιστί</h1><div class=\"entry-meta\"><span>DGP · ordem 904 na letra α · nº geral 904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em língua egípcia 2 como egípcio; com astúcia. 〈Αἴγυπτος〉</p></section></article>\n<article id=\"entry-dgp-905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγυπτογενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 905 na letra α · nº geral 905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nascido no Egito 2 descendente de Egípcio. 〈Αἴγυπτος, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰγυπτόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 906 na letra α · nº geral 906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção ao Egito. 〈Αἴγυπτος〉</p></section></article>\n<article id=\"entry-dgp-907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴγυπτος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 907 na letra α · nº geral 907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Egito, n. de homem 2 o Nilo.</p></section></article>\n<article id=\"entry-dgp-908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἴγυπτος2, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 908 na letra α · nº geral 908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Egito.</p></section></article>\n<article id=\"entry-dgp-909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀίδας</h1><div class=\"entry-meta\"><span>DGP · ordem 909 na letra α · nº geral 909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = Ἅιδης.</p></section></article>\n<article id=\"entry-dgp-910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδεῖο</h1><div class=\"entry-meta\"><span>DGP · ordem 910 na letra α · nº geral 910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. pres. ép. de αἰδέομαι.</p></section></article>\n<article id=\"entry-dgp-911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 911 na letra α · nº geral 911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. αἰδέσομαι, aor. ᾐδεσάμην ou ᾐδέσθην, perf. ᾔδεσμαι) 1 ter pudor: οἴη δ’ οὐκ εἴσειμι μετ’ ἀνέρας, αἰδέομαι hom. sozinha não iria para o meio dos homens, por pudor 2 ter escrúpulo; ter vergonha de, temer, inf., part., ἐπί e dat.: ἐκβαλεῖν αἰδοῦμαι δάκρυ eur. tenho vergonha de verter uma lágrima, αἴδεσαι μὲν πατέρα τὸν σὸν ἐν λυγρῷ γήρᾳ προλείπων sóf. tem pudor de abandonar teu pai na triste velhice, οἱ δ’ αἰδεσθέντες ἐπὶ τῷ ἔργῳ d.h. os que se envergonharam dessa ação 3 reverenciar; tratar com deferência: δεῖ τοὺς θεοὺς σέβεσθαι, γονέας τιμᾶν, πρεσβυτέρους αἰδεῖσθαι plut. deve-se venerar os deuses, honrar os pais, respeitar os mais idosos, τόνδ’ ὅρκον αἰδεσθεὶς θεῶν sóf. respeitando este juramento feito aos deuses 4 ter compaixão de; ser indulgente com, ac. e ὑπέρ e gen.: ἕως ἂν αἰδέσηταί τινα τῶν ἐν γένει τοῦ πεπονθότος dem. até que ele tenha acolhido um dos parentes da vítima (para tratar de um acordo sobre um assassínio), αἰδουμένους ὑπὲρ τῆς ἀνθρωπίνης φύσεως plut. sendo indulgente com a natureza humana 5 obter o perdão de alguém, ac. 〈αἰδώς〉</p></section></article>\n<article id=\"entry-dgp-912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴδεσθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 912 na letra α · nº geral 912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. de αἰδέομαι.</p></section></article>\n<article id=\"entry-dgp-913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδέσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 913 na letra α · nº geral 913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">respeitável; venerável; sagrado. 〈αἰδέομαι〉</p></section></article>\n<article id=\"entry-dgp-914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδεσίμως</h1><div class=\"entry-meta\"><span>DGP · ordem 914 na letra α · nº geral 914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com respeito; respeitosamente.</p></section></article>\n<article id=\"entry-dgp-915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴδεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 915 na letra α · nº geral 915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 piedade; compaixão; perdão 2 respeito; veneração 3 Jur. acordo. 〈αἰδέομαι〉</p></section></article>\n<article id=\"entry-dgp-916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴδεσσαι</h1><div class=\"entry-meta\"><span>DGP · ordem 916 na letra α · nº geral 916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor. ép. de αἰδέομαι.</p></section></article>\n<article id=\"entry-dgp-917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδέσσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 917 na letra α · nº geral 917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ép. de αἰδέομαι.</p></section></article>\n<article id=\"entry-dgp-918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδεστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 918 na letra α · nº geral 918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">respeitável; venerável. 〈αἰδέομαι〉</p></section></article>\n<article id=\"entry-dgp-919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐδηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 919 na letra α · nº geral 919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz desaparecer; que destrói; funesto 2 que não se pode olhar; horrível 3 invisível; secreto (ações, ritos); obscuro (palavras) 3 sombrio; obscuro. 〈ἀ-, ἰδεῖν〉</p></section></article>\n<article id=\"entry-dgp-920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊδήλως</h1><div class=\"entry-meta\"><span>DGP · ordem 920 na letra α · nº geral 920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de maneira funesta.</p></section></article>\n<article id=\"entry-dgp-921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδημόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 921 na letra α · nº geral 921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com pudor; com modéstia.</p></section></article>\n<article id=\"entry-dgp-922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 922 na letra α · nº geral 922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος cheio de temor respeitoso; reservado; discreto. 〈αἰδέομαι〉</p></section></article>\n<article id=\"entry-dgp-923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἅιδης</h1><div class=\"entry-meta\"><span>DGP · ordem 923 na letra α · nº geral 923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ᾅδης, jôn. ép. Ἀΐδης, ου (ὁ) 1 Hades, deus dos infernos; εἰς Ἅιδου, ἐν Ἅιδου na morada de Hades; nos infernos 2 Hades, a morte. 〈ἀ-, ἰδεῖν〉</p></section></article>\n<article id=\"entry-dgp-924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 924 na letra α · nº geral 924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que dura sempre; eterno; perpétuo; ἐς ἀΐδιον para sempre. 〈ἄϊ〉</p></section></article>\n<article id=\"entry-dgp-925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 925 na letra α · nº geral 925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invisível; sombrio; escuro. 〈ἀ-, ἰδεῖν〉</p></section></article>\n<article id=\"entry-dgp-926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδοῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 926 na letra α · nº geral 926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 venerável; respeitável; sagrado 2 respeitoso; cheio de deferência (palavras, atitudes) 3 vergonhoso; vil ♦ τὸ αἰδοῖον, τὰ αἰδοῖα 4 as partes pudendas. 〈αἰδώς〉</p></section></article>\n<article id=\"entry-dgp-927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδοίως</h1><div class=\"entry-meta\"><span>DGP · ordem 927 na letra α · nº geral 927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com respeito; respeitosamente.</p></section></article>\n<article id=\"entry-dgp-928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴδομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 928 na letra α · nº geral 928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = αἰδέομαι.</p></section></article>\n<article id=\"entry-dgp-929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἄϊδος, Ἄϊδι, Ἄϊδα</h1><div class=\"entry-meta\"><span>DGP · ordem 929 na letra α · nº geral 929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Ἄϊς e Ἁίδης.</p></section></article>\n<article id=\"entry-dgp-930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 930 na letra α · nº geral 930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 respeitoso 2 compassivo; humano. 〈αἰδώς, φρήν〉</p></section></article>\n<article id=\"entry-dgp-931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊδρεΐη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 931 na letra α · nº geral 931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ignorância; imperícia. 〈ἀ-, ἴδρις〉</p></section></article>\n<article id=\"entry-dgp-932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊδρηΐη</h1><div class=\"entry-meta\"><span>DGP · ordem 932 na letra α · nº geral 932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἀϊδρεΐη.</p></section></article>\n<article id=\"entry-dgp-933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊδρις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 933 na letra α · nº geral 933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιος e εος ignorante; inexperiente. 〈ἀ-, ἴδρις〉</p></section></article>\n<article id=\"entry-dgp-934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αΐδω</h1><div class=\"entry-meta\"><span>DGP · ordem 934 na letra α · nº geral 934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἀείδω.</p></section></article>\n<article id=\"entry-dgp-935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀϊδωνευς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 935 na letra α · nº geral 935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Edoneu, outro n. de Hades.</p></section></article>\n<article id=\"entry-dgp-936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰδώς, όος-οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 936 na letra α · nº geral 936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 temor respeitoso; respeito; deferência: αἰδῶ ἑαυτοῦ τοῖς στρατιώταις ἐμποιῆσαι xen. infundir um temor respeitoso nos soldados, οἱ τοὺς θεοὺς δι᾽ αἰδοῦς ἔχοντες el. aqueles que reverenciam os deuses 2 sentimento de honra; brio; dignidade de conduta: δι᾽ αἰδοῦς ὄμμ’ ἔχουσα eur. tendo pudor nos olhos, αἰδὼς σωφροσύνης πλεῖστον μετέχει tuc. o sentimento da honra tem muitíssimo de sabedoria, αἰδοῦς ἐμπίπλασθαι xen. estar cheio de modéstia; αἰδώς ἐστι teme-se, com inf. 3 sentimento de vergonha; caráter vergonhoso (de uma ação): δακρύων αἰδῶ ésql. vergonha das lágrimas 4 rar. partes pudendas 5 rar. caráter que inspira um temor respeitoso; grandeza respeitável; dignidade 6 compaixão; misericórdia.</p></section></article>\n<article id=\"entry-dgp-937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄϊε, ἄϊεν</h1><div class=\"entry-meta\"><span>DGP · ordem 937 na letra α · nº geral 937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. de ἀΐω1.</p></section></article>\n<article id=\"entry-dgp-938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰεί</h1><div class=\"entry-meta\"><span>DGP · ordem 938 na letra α · nº geral 938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἀεί.</p></section></article>\n<article id=\"entry-dgp-939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰειγενέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 939 na letra α · nº geral 939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) poét. imortal. 〈αἰεί, γίγνομαι〉</p></section></article>\n<article id=\"entry-dgp-940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰείμνηστος</h1><div class=\"entry-meta\"><span>DGP · ordem 940 na letra α · nº geral 940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἀείμνηστος.</p></section></article>\n<article id=\"entry-dgp-941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰέλουρος</h1><div class=\"entry-meta\"><span>DGP · ordem 941 na letra α · nº geral 941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = αἴλουρος.</p></section></article>\n<article id=\"entry-dgp-942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰέν</h1><div class=\"entry-meta\"><span>DGP · ordem 942 na letra α · nº geral 942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e αἰές poét. = ἀεί.</p></section></article>\n<article id=\"entry-dgp-943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰετός</h1><div class=\"entry-meta\"><span>DGP · ordem 943 na letra α · nº geral 943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἀετός.</p></section></article>\n<article id=\"entry-dgp-944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰζήϊος</h1><div class=\"entry-meta\"><span>DGP · ordem 944 na letra α · nº geral 944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = αἰζηός.</p></section></article>\n<article id=\"entry-dgp-945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀΐζηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 945 na letra α · nº geral 945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">invisível. 〈ἀ-, ἰδεῖν〉</p></section></article>\n<article id=\"entry-dgp-946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰζηός, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 946 na letra α · nº geral 946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 viril; robusto;vigoroso ♦ οἱ αἰζηοί 2 homens fortes.</p></section></article>\n<article id=\"entry-dgp-947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰήτας, αο</h1><div class=\"entry-meta\"><span>DGP · ordem 947 na letra α · nº geral 947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = Αἰήτης.</p></section></article>\n<article id=\"entry-dgp-948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰήτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 948 na letra α · nº geral 948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eetes, rei da Cólquida.</p></section></article>\n<article id=\"entry-dgp-949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 949 na letra α · nº geral 949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">duv. impetuoso; de sopro ruidoso. 〈ἄημι〉</p></section></article>\n<article id=\"entry-dgp-950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθ’</h1><div class=\"entry-meta\"><span>DGP · ordem 950 na letra α · nº geral 950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. αἴθε e αἴτε.</p></section></article>\n<article id=\"entry-dgp-951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθαιεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 951 na letra α · nº geral 951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante de Etéia, na Lacônia.</p></section></article>\n<article id=\"entry-dgp-952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθαλόεις-οῦς, όεσσα-οῦσσα, όεν-οῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 952 na letra α · nº geral 952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enegrecido; fusco 2 castanho escuro 3 que queima; que consome. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθαλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 953 na letra α · nº geral 953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fumaça negra e espessa; fuligem ♦ adj. 2 enegrecido pelo fogo 3 castanho escuro. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθαλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 954 na letra α · nº geral 954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 reduzir a cinza; consumir 2 sujar com fumaça. 〈αἴθαλος〉</p></section></article>\n<article id=\"entry-dgp-955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθε</h1><div class=\"entry-meta\"><span>DGP · ordem 955 na letra α · nº geral 955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εἴθε.</p></section></article>\n<article id=\"entry-dgp-956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθέριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 956 na letra α · nº geral 956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do éter; produzido no éter; etéreo. 〈αἰθήρ〉</p></section></article>\n<article id=\"entry-dgp-957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθεροειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 957 na letra α · nº geral 957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante ao éter; etéreo. 〈αἰθήρ, εἷδος〉</p></section></article>\n<article id=\"entry-dgp-958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθερώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 958 na letra α · nº geral 958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">αἰθεροειδής.</p></section></article>\n<article id=\"entry-dgp-959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθήρ, έρος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 959 na letra α · nº geral 959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 éter, a mais alta região do ar 2 éter, morada dos astros e deuses 3 ar, elemento 4 ar; clima 5 fôlego; respiração 6 Éter, person. filho de Érebo e da Noite. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιοπεύς, έως</h1><div class=\"entry-meta\"><span>DGP · ordem 960 na letra α · nº geral 960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ῆος (ὁ) etíope. 〈Αἰθίοψ〉</p></section></article>\n<article id=\"entry-dgp-961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιοπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 961 na letra α · nº geral 961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Etiópia.</p></section></article>\n<article id=\"entry-dgp-962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιοπίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 962 na letra α · nº geral 962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Αἰθιοπία.</p></section></article>\n<article id=\"entry-dgp-963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιοπικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 963 na letra α · nº geral 963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Αἰθιόπιος. 〈Αἰθίοψ〉</p></section></article>\n<article id=\"entry-dgp-964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιόπιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 964 na letra α · nº geral 964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">etíope. 〈Αἰθίοψ〉</p></section></article>\n<article id=\"entry-dgp-965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθιοπίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 965 na letra α · nº geral 965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) etíope. 〈Αἰθίοψ〉</p></section></article>\n<article id=\"entry-dgp-966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Αἰθίοψ, οπος</h1><div class=\"entry-meta\"><span>DGP · ordem 966 na letra α · nº geral 966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 etíope: ποταμὸς Αἰθίοψ o rio etíope, o Nilo superior ♦ ὁ Αἰθίοψ 2 o Etíope, epít. de Zeus. 〈αἴθω, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 967 na letra α · nº geral 967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 queimado; escuro 2 cor de fogo; resplandecente. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθουσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 968 na letra α · nº geral 968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pórtico; galeria; varanda. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷθοψ, οπος</h1><div class=\"entry-meta\"><span>DGP · ordem 969 na letra α · nº geral 969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 de aspecto abrasador; que esquenta; que queima 2 de aspecto abrasado ou inflamado; cintilante; resplandecente 3 violento; furioso. 〈αἴθω, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 970 na letra α · nº geral 970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">brilho do éter; serenidade do céu. 〈αἰθήρ〉</p></section></article>\n<article id=\"entry-dgp-971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθρηγενέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 971 na letra α · nº geral 971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido do éter, epit. de Bóreas. 〈αἴθρη, γένος〉</p></section></article>\n<article id=\"entry-dgp-972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθρηγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 972 na letra α · nº geral 972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">αἰθρηγενέτης.</p></section></article>\n<article id=\"entry-dgp-973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 973 na letra α · nº geral 973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ar puro; céu sereno 2 ar livre. 〈αἴθριος〉</p></section></article>\n<article id=\"entry-dgp-974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθριάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 974 na letra α · nº geral 974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intr. estar ao ar livre 2 expor ao ar livre, sob um céu sereno 3 tornar o céu sereno 4 tard. acalmar-se. 〈αἰθρία〉</p></section></article>\n<article id=\"entry-dgp-975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 975 na letra α · nº geral 975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 puro; sereno 2 exposto ao ar livre ♦ τὸ αἴθριον 3 pátio, considerado como a parte que recebe a influência do éter. 〈αἴθρα〉</p></section></article>\n<article id=\"entry-dgp-976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἷθρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 976 na letra α · nº geral 976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ar frio; frescor da manhã. 〈αἴθρα〉</p></section></article>\n<article id=\"entry-dgp-977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθυγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 977 na letra α · nº geral 977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">centelha; clarão. 〈αἰθύσσω〉</p></section></article>\n<article id=\"entry-dgp-978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθυια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 978 na letra α · nº geral 978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gaivota.</p></section></article>\n<article id=\"entry-dgp-979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰθύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 979 na letra α · nº geral 979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitar vivamente; chacoalhar 2 agitar-se; vacilar. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθω</h1><div class=\"entry-meta\"><span>DGP · ordem 980 na letra α · nº geral 980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 acender (o fogo); fazer brilhar (uma luz) 2 queimar (vítimas) 3 intr. queimar; arder ♦ méd. 4 queimar-se; brilhar; arder (de amor).</p></section></article>\n<article id=\"entry-dgp-981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἴθων, ονος</h1><div class=\"entry-meta\"><span>DGP · ordem 981 na letra α · nº geral 981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ωνος (masc., fem.) 1 resplandecente; brilhante; refulgente 2 da cor do fogo; vermelho escuro; ruivo 3 ardente; fogoso. 〈αἴθω〉</p></section></article>\n<article id=\"entry-dgp-982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 982 na letra α · nº geral 982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ᾔκαλλον) afagar; lisonjear; acolher com alegria.</p></section></article>\n<article id=\"entry-dgp-983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκέλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 983 na letra α · nº geral 983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀεικέλιος.</p></section></article>\n<article id=\"entry-dgp-984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀϊκή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 984 na letra α · nº geral 984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impulso; ímpeto. 〈ἀΐσσω〉</p></section></article>\n<article id=\"entry-dgp-985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">αἰκής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 985 na letra α · nº geral 985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀεικής.</p></section></article>\n";
